"""Audit user-returned NROM467 hardware logs without changing their bytes."""
import argparse,hashlib,json,re
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--raw',required=True,type=Path);p.add_argument('--out',required=True,type=Path);a=p.parse_args()
files={n:(a.raw/n).read_bytes() for n in ['nes-progress-227.txt','nes-budget-227.txt','nes-game-last-227.txt']}
last=dict(s.split('=',1) for s in files['nes-game-last-227.txt'].decode().splitlines() if '=' in s)
marks={m[1]:int(m[2]) for m in re.finditer(r'stage=(\S+).*?elapsed_ms=(\d+)',files['nes-progress-227.txt'].decode())}
for k,v in {'board_observed_hex':'78','loaded_bytes':'393216','compared_bytes':'393216','verified':'1','stop_ok':'1','base_restored':'1','safe_to_reload':'1','run_passed':'1','run_error':'0','verify_error':'0','native_sink_error':'0','native_video_error':'0','trace_aborts':'0'}.items():assert last[k]==v,(k,last.get(k))
window=(marks['DISPLAY_STOPPED']-marks['DISPLAY_NEXT'])/1000;frames=int(last['native_frames']);assert frames==int(last['trace_commits']) and int(last['sink_window_sent'])==int(last['sink_window_retired'])
budget=files['nes-budget-227.txt'].decode();bins=[list(int(x,16) for x in m[1].split(',')) for m in re.finditer(r'^b\d+=(.*)$',budget,re.M)];assert sum(v[0] for v in bins)==frames
r={'limited_hardware_smoke_passed':True,'FPGA':457,'ARM':418,'fixture':428,'display_window_seconds':window,'display_completed_frames':frames,'mean_display_completions_per_second':frames/window,'fps60_proven':False,'source_capture_no_loss_proven':False,'pixel_exact_display_proven':False,'user_observation':{'A_hold':'red grid maintained','A_release':'blue grid restored','menu_return':'normal after about 60 seconds'},'video_review':{'duration_seconds':56.07,'sampled_frames':'blue/red/blue verified; full menu return from user and progress log','pixel_comparison':'not performed'},'progress_ms':marks,'termination':{'native_result':int(last['native_result']),'receiver_error':int(last['native_receiver_error']),'interpretation':'result1 is session deadline; receiver23 combines callback false and CRC mismatch, so it is not independent proof of a CRC fault; callback guard can return false at deadline'},'pad_trace_note':'zero records; recorder requires completed 8-bit reads while fixture reads only A bit; input effect observed in video/user report','metadata_note':'legacy candidate=NES-GAME-227 and board_expected_hex=74 are logging constants; observed ID78 is correct; next builder labels trial and expected ID78','phase_ticks_10ms':{k:int(last[k]) for k in ['profile_receive_ticks','profile_build_stage_ticks','profile_seal_ack_ticks']},'input_sha256':{n:hashlib.sha256(v).hexdigest() for n,v in files.items()},'scope':'user physical trial of paired 467; MCU-reported verification, display completions, STOP/base token/menu copy plus visual input and user menu confirmation; no complete STA/CDC signoff or 60fps'}
a.out.parent.mkdir(parents=True,exist_ok=True);a.out.write_text(json.dumps(r,indent=2)+'\n',encoding='utf8');print(json.dumps({'smoke':True,'seconds':window,'frames':frames,'display_rate':frames/window,'budget_bins':len(bins)}))
